// Normalize whatever the telephony provider sent into { called, caller }.
const b = ($input.first().json || {}).body || {};
const e164 = (v) => {
  const d = String(v || '').replace(/[^\d+]/g, '');
  if (/^\+\d{10,15}$/.test(d)) return d;
  if (/^1\d{10}$/.test(d)) return '+' + d;
  if (/^\d{10}$/.test(d)) return '+1' + d;
  return null;
};
// Common provider field names, in preference order.
const called = e164(b.called || b.To || b.to || b.calledNumber || b.destination);
const caller = e164(b.caller || b.From || b.from || b.callerNumber || b.origin);
if (!called || !caller) {
  return [{ json: { invalid: true, error: 'could not read called/caller from payload', raw: JSON.stringify(b).slice(0, 400) } }];
}
return [{ json: { invalid: false, called, caller, caller_name: b.caller_name || b.CallerName || null } }];

// Decide whether we may text right now, and compose the message.
// TCPA: artificial/prerecorded and automated texts stay inside 8am-9pm in the
// RECIPIENT's local time; we use the client's timezone as the proxy since the
// caller just dialed their local business.
const client = $('Client Active? (kill switch)').first().json;
const call = $('Normalize Call').first().json;
const suppressed = ($input.all() || []).some((i) => i.json && i.json.id);

const tz = client.timezone || 'America/Los_Angeles';
const now = new Date();
const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: tz, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit',
}).formatToParts(now);
const get = (t) => parts.find((p) => p.type === t).value;
const hour = Number(get('hour'));
const minute = Number(get('minute'));
const dow = get('weekday').toLowerCase();
const insideTcpa = hour >= 8 && hour < 21;

// after_hours = outside the CLIENT's own business hours (a billing/renewal
// signal, separate from the legal sending window).
const hours = client.business_hours || {};
const span = hours[dow];
let afterHours = true;
if (Array.isArray(span) && span.length === 2) {
  const mins = hour * 60 + minute;
  const toMin = (s) => Number(String(s).split(':')[0]) * 60 + Number(String(s).split(':')[1] || 0);
  afterHours = !(mins >= toMin(span[0]) && mins < toMin(span[1]));
}

const brand = client.brand_name || client.company_name;
const template = client.textback_message ||
  'Sorry we missed your call - this is {brand}. What do you need help with? Reply here and we will get right back to you.';
const message = template.replace(/\{brand\}/g, brand) + '\n\nReply STOP to opt out.';

return [{ json: {
  client_id: client.id,
  brand,
  from_number: client.sending_number || client.inbound_number,
  to_number: call.caller,
  caller_name: call.caller_name,
  message,
  after_hours: afterHours,
  suppressed,
  inside_tcpa: insideTcpa,
  may_send: !suppressed && insideTcpa,
  escalation_phone: client.escalation_phone,
  escalation_email: client.escalation_email,
  local_time: hour + ':' + String(minute).padStart(2, '0') + ' ' + tz,
} }];

// Tell the owner a call was missed and caught, so they can jump in if they want.
const g = $('Compose + Gate').first().json;
const when = g.after_hours ? 'while they were closed' : 'during business hours';
return [{ json: {
  to: g.escalation_phone,
  email: g.escalation_email,
  brand: g.brand,
  body: 'Missed call from ' + g.to_number + ' ' + when + '. We texted them automatically' +
        (g.may_send ? '.' : ' - queued until 8am (outside legal texting hours).'),
  sendAlert: !!g.escalation_phone,
} }];
